/**
 * Builds an argv-style array like the one the real binary passes to execute().
 * @param {...string} args The CLI arguments.
 * @returns {string[]} The argv array.
 */
function argv(...args) {
	return ["node", "eslint.js", ...args];
}

/**
 * Creates a temporary directory that is removed after the test.
 * @returns {string} The temporary directory path.
 */
function makeTempDir() {
	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-cli-test-"));
	tempDirs.push(dir);
	return dir;
}

/**
 * Creates a lint message.
 * @param {number} severity The message severity.
 * @param {string} ruleId The rule id.
 * @param {Object} [overrides] Additional message properties.
 * @returns {Object} The lint message.
 */
function makeMessage(severity, ruleId = "test-rule", overrides = {}) {
	return {
		ruleId,
		severity,
		message: "A problem",
		line: 1,
		column: 1,
		nodeType: "Program",
		...overrides,
	};
}

/**
 * Creates a lint result with counts derived from its messages.
 * @param {Object} [options] Result options.
 * @param {string} [options.filePath] The result file path.
 * @param {Object[]} [options.messages] The result messages.
 * @param {Object} [overrides] Additional result properties.
 * @returns {Object} The lint result.
 */
function makeResult(
	{ filePath = path.join(process.cwd(), "file.js"), messages = [] } = {},
	overrides = {},
) {
	let errorCount = 0;
	let warningCount = 0;
	let fatalErrorCount = 0;

	for (const message of messages) {
		if (message.fatal || message.severity === 2) {
			errorCount += 1;
			if (message.fatal) {
				fatalErrorCount += 1;
			}
		} else {
			warningCount += 1;
		}
	}

	return {
		filePath,
		messages,
		suppressedMessages: [],
		errorCount,
		fatalErrorCount,
		warningCount,
		fixableErrorCount: 0,
		fixableWarningCount: 0,
		...overrides,
	};
}

/**
 * Writes a suppressions file into a directory.
 * @param {string} dir The directory.
 * @param {Object} contents The suppressions contents.
 * @param {string} [fileName] The suppressions file name.
 * @returns {string} The suppressions file path.
 */
function writeSuppressions(
	dir,
	contents,
	fileName = "eslint-suppressions.json",
) {
	const filePath = path.join(dir, fileName);

	fs.writeFileSync(filePath, JSON.stringify(contents, null, 2));
	return filePath;
}

