	test("writes formatter output to --output-file including parent directories", async () => {
		const dir = makeTempDir();
		const outputFile = path.join(dir, "nested", "report.txt");

		formatMock.mockResolvedValue("written report");

		const exitCode = await cli.execute(
			argv("--output-file", outputFile, "file.js"),
