					schema: [],
				},
				create(context) {
					return {
						Identifier(node) {
							if (node.name === "foo") {
								context.report({
									node,
									message: "Do not use foo.",
								});
							}
						},
					};
				},
			},
		},
	};

	it("returns an empty object for empty results", async () => {
		const cwd = await createTempDir();
