							Identifier(node) {
								if (node.name === "foo") {
									context.report({
										node,
										message: "Do not use foo.",
									});
								}
							},
						};
					},
				},
			},
		};

		await fs.writeFile(
			formatterFilePath,
			`module.exports = function formatter(results, context) {
				return JSON.stringify({
					filePaths: results.map(result => result.filePath),
					cwd: context.cwd,
					maxWarnings: context.maxWarnings,
					rulesMeta: context.rulesMeta
				});
			};\n`,
		);

		const eslint = new ESLint({
			cwd,
