			filePath: "b.js",
		});
		const second = await eslint.lintText("foo;\n", {
			filePath: "a.js",
		});
		const results = [first[0], second[0]];
		const formatter = await eslint.loadFormatter("./formatter.cjs");

		const formatted = JSON.parse(
			formatter.format(results, { maxWarnings: 7 }),
		);

		expect(formatted.filePaths).toEqual([
			path.join(cwd, "a.js"),
			path.join(cwd, "b.js"),
